import numpy as np
from numba import njit, prange
from concurrent.futures import ProcessPoolExecutor
import time

# Primality check with Numba JIT
@njit
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(np.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

# BBP-inspired step function with Numba JIT
@njit
def bbp_delta(n):
    step = 0.0
    for k in range(1, 5):
        step += (16 ** (1 - k)) / (8 * k + n % 7 + 1)
    return int(step) + 1

# CPU-based twin prime finder
@njit
def find_twin_primes_cpu(start, end):
    results = []
    current = start
    while current < end:
        if is_prime(current) and is_prime(current + 2):
            results.append((current, current + 2))
        step = bbp_delta(current)
        current += step
    return results

# Parallel runner
def run_cpu_parallel(limit, num_chunks=8):
    chunk_size = limit // num_chunks
    ranges = [(3 + i * chunk_size, min(limit, 3 + (i + 1) * chunk_size)) for i in range(num_chunks)]

    results = []
    with ProcessPoolExecutor(max_workers=num_chunks) as executor:
        futures = [executor.submit(find_twin_primes_cpu.py_func, start, end) for start, end in ranges]
        for future in futures:
            results.extend(future.result())

    return results

# Start timing for CPU version
start_time = time.time()
cpu_results = run_cpu_parallel(10_000_0, num_chunks=4)  # Small test limit due to environment constraints
end_time = time.time()

len(cpu_results), end_time - start_time

